import{_ as a,C as i,c as l,o as g,a3 as o,G as r,j as s,a as n}from"./chunks/framework.Dokpd4od.js";const k=JSON.parse('{"title":"Deliveries","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/operations/deliveries.md","filePath":"master/supply-chain/inventories/operations/deliveries.md","lastUpdated":1793074831000}'),d={name:"master/supply-chain/inventories/operations/deliveries.md"};function h(c,e,u,p,m,v){const t=i("ImagePopup");return g(),l("div",null,[e[0]||(e[0]=o('<h1 id="deliveries" tabindex="-1">Deliveries <a class="header-anchor" href="#deliveries" aria-label="Permalink to &quot;Deliveries&quot;">​</a></h1><p>A delivery records goods that leave for a customer. When you validate it, the quantities leave your stock. Most deliveries are created when you confirm a sales order, so your job is to reserve the goods, pack them and click <strong>Validate</strong>.</p><blockquote><p><strong>In simple words:</strong> A delivery says &quot;we shipped this to the customer&quot;. Validate it and the products leave your stock.</p></blockquote><p>Open <code>Inventory → Operations → Transfers → Deliveries</code>.</p><h2 id="worked-scenario-ship-so-3" tabindex="-1">Worked scenario: ship SO/3 <a class="header-anchor" href="#worked-scenario-ship-so-3" aria-label="Permalink to &quot;Worked scenario: ship SO/3&quot;">​</a></h2><p>Sales order <strong>SO/3</strong> sells 3 <strong>Digital Drawing Tablet</strong> and 6 <strong>Stay Warm Electric Warm Blankets</strong>.</p><ol><li>Confirm the sales order. See <a href="./../../../sales/sales/quotations-orders/manage-orders.html">Manage orders</a>.</li><li>Open the order. Click <strong>Deliveries</strong> in the switcher at the top to open the sub page <strong>Manage SO/3 Deliveries</strong>. It lists the delivery documents with <strong>Source Document</strong> <strong>SO/3</strong>.</li></ol>',7)),r(t,{src:"/images1/inventory/delv_from_so.png",alt:"Manage SO/3 Deliveries sub page listing the delivery documents for sales order SO/3"}),e[1]||(e[1]=s("ol",{start:"3"},[s("li",null,[n("Open the delivery from "),s("code",null,"Inventory → Operations → Transfers → Deliveries"),n(".")])],-1)),r(t,{src:"/images1/inventory/delv_list.png",alt:"Deliveries list searched for WH/OUT with Ready and Done deliveries"}),e[2]||(e[2]=o('<ol start="4"><li>If the state is <strong>Draft</strong>, click <strong>Mark as Todo</strong>. With no stock in the source location (for example <strong>WH/Output</strong>), the state becomes <strong>Waiting</strong> and the buttons are <strong>Check Availability</strong>, <strong>Validate</strong>, <strong>Cancel</strong>, <strong>Print</strong> and <strong>Delete</strong>. Click <strong>Check Availability</strong> to reserve stock. With stock available (for example in <strong>WH/Stock</strong>), the state goes straight to <strong>Ready</strong>.</li><li>Check the <strong>Operations</strong> table. <strong>Demand</strong> is what the customer ordered. A <strong>Ready</strong> delivery has no <strong>Check Availability</strong> button.</li></ol>',1)),r(t,{src:"/images1/inventory/delv_view_ready.png",alt:"Delivery WH/OUT/00045 in Ready state with source WH/Stock, the Validate, Cancel, Print and Delete buttons and the Operations table"}),e[3]||(e[3]=o('<ol start="6"><li>Turn on <strong>Picked</strong> or fill <strong>Quantity</strong> for what you hand to the carrier. Click <strong>Save changes</strong> if you edited the lines.</li><li>Click <strong>Validate</strong>. The state becomes <strong>Done</strong>. Only <strong>Return</strong> and <strong>Print</strong> remain.</li></ol>',1)),r(t,{src:"/images1/inventory/delv_done.png",alt:"Delivery WH/OUT/42 in Done state with contact My Company and only the Return and Print buttons"}),e[4]||(e[4]=o('<ol start="8"><li>Open the sales order. The <strong>Delivered</strong> column now shows the quantities.</li></ol><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><ul><li><strong><em>Delivery Address:</em></strong> The customer. The order fills it in.</li><li><strong><em>Operation Type:</em></strong> Required. Usually <strong>My Company: Delivery Orders</strong>.</li><li><strong><em>Source Location:</em></strong> Required. With one step, goods leave <strong>WH/Stock</strong>. With three steps, the delivery takes them from <strong>WH/Output</strong> after Pick and Pack.</li><li><strong><em>Responsible</em></strong>, <strong><em>Scheduled At</em></strong> and <strong><em>Source Document</em></strong> work as on a receipt.</li></ul><p>To start by hand, click <strong>New Delivery</strong>, fill the customer and the lines, then click <strong>Create</strong>. You can also click <strong>Create &amp; create another</strong> or <strong>Cancel</strong>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>After <strong>Create</strong> you stay on the <strong>Edit</strong> page of the new delivery.</p></div><h2 id="cancel-a-delivery" tabindex="-1">Cancel a delivery <a class="header-anchor" href="#cancel-a-delivery" aria-label="Permalink to &quot;Cancel a delivery&quot;">​</a></h2><p>Click <strong>Cancel</strong>. Aureus asks &quot;Are you sure you would like to do this?&quot;. Click <strong>Confirm</strong> to cancel, or <strong>Cancel</strong> to go back. The state bar then highlights <strong>Canceled</strong> and only <strong>Print</strong> and <strong>Delete</strong> remain.</p><h2 id="check-availability" tabindex="-1">Check Availability <a class="header-anchor" href="#check-availability" aria-label="Permalink to &quot;Check Availability&quot;">​</a></h2><p>Stock is reserved when you confirm the order if the operation type&#39;s reservation method is <strong>At Confirm</strong>. If it is <strong>Manual</strong>, or stock arrived later, click <strong>Check Availability</strong>. The button shows on <strong>Waiting</strong> documents. It does not show on <strong>Ready</strong> ones.</p><p>If you validate with nothing reserved, Aureus shows <strong>No quantities are reserved</strong>.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>Validation moves stock from your outgoing location to <strong>Partners/Customers</strong>. The prefix is <strong>OUT</strong>, such as <strong>WH/OUT/42</strong>. In the example warehouse the chain is <strong>WH/PICK</strong> from <strong>WH/Stock</strong> to <strong>WH/Packing Zone</strong>, <strong>WH/PACK</strong> to <strong>WH/Output</strong>, and <strong>WH/OUT</strong> to the customer. For <strong>SO/3</strong> these are <strong>WH/PICK/1</strong>, <strong>WH/PACK/41</strong> and <strong>WH/OUT/42</strong>. See <a href="./../routes/three-step-flow.html">Three-step flow</a>.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Mark as Todo:</strong> confirms a <strong>Draft</strong> delivery.</li><li><strong>Check Availability:</strong> reserves stock on a <strong>Waiting</strong> delivery.</li><li><strong>Validate:</strong> ships the goods and sets <strong>Done</strong>.</li><li><strong>Cancel:</strong> stops the delivery after you confirm.</li><li><strong>Print:</strong> always shown. <strong>Delete:</strong> shown while the delivery is not <strong>Done</strong>.</li><li><strong>Return:</strong> brings goods back after <strong>Done</strong>. See <a href="./backorders-and-returns.html">Backorders and returns</a>.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./receipts.html">Receipts</a></li><li><a href="./">Transfers</a></li><li><a href="./print-documents.html">Print documents</a></li><li><a href="./../../../sales/sales/quotations-orders/manage-orders.html">Manage orders</a></li></ul>',16))])}const f=a(d,[["render",h]]);export{k as __pageData,f as default};
